control:lum_script.script:
(function () {
	var endpoint = g_LumisRootPath + "br/com/lumis/commons/contentmigrator/hierarchicalcontentmigration/status";
	// Rendered by the server in the user's locale; keep one translate tag per line.
	var labels = {
		STOPPED: "<lum:translate>STR_STATUS_STOPPED</lum:translate>",
		STOPPED_WITH_ERROR: "<lum:translate>STR_STATUS_STOPPED_WITH_ERROR</lum:translate>",
		RUNNING: "<lum:translate>STR_STATUS_RUNNING</lum:translate>",
		FINISHED: "<lum:translate>STR_STATUS_FINISHED</lum:translate>"
	};
	function refreshMigrationStatuses() {
		fetch(endpoint, { credentials: "same-origin", headers: { "Accept": "application/json" } })
			.then(function (response) { if (!response.ok) throw new Error("status request failed"); return response.json(); })
			.then(function (items) {
				items.forEach(function (item) {
					var selector = 'input[name="migrationList.tabulardata"][value="' + item.id + '"]';
					var row = document.querySelector(selector);
					if (!row) return;
					var itemRow = row.closest("li.lum-list-item");
					if (!itemRow) return;
					var status = itemRow.querySelector(".lum-field-id-statusLabel .lum-field-value");
					var total = itemRow.querySelector(".lum-field-id-totalCount .lum-field-value");
					var migrated = itemRow.querySelector(".lum-field-id-migratedCount .lum-field-value");
					if (status) status.textContent = labels[item.status] || item.status;
					if (total) total.textContent = item.totalCount;
					if (migrated) migrated.textContent = item.migratedCount;
				});
			})
			.catch(function () { /* Keep the last rendered status if polling fails. */ });
	}
	window.setInterval(refreshMigrationStatuses, 60000);
})();

(function () {
	var BASE = g_LumisRootPath + "br/com/lumis/commons/contentmigrator/hierarchicalcontentmigration";
	var PAGE_SIZE = 200;
	var COUNT_DELAY = 500;
	// Rendered by the server in the user's locale; keep one translate tag per line.
	var text = {
		breadcrumb: "<lum:translate>STR_HCM_BREADCRUMB</lum:translate>",
		root: "<lum:translate>STR_HCM_ROOT</lum:translate>",
		rootLevel: "<lum:translate>STR_HCM_ROOT_LEVEL</lum:translate>",
		level: "<lum:translate>STR_HCM_LEVEL</lum:translate>",
		levelOpened: "<lum:translate>STR_HCM_LEVEL_OPENED</lum:translate>",
		chooseOrigin: "<lum:translate>STR_HCM_CHOOSE_ORIGIN</lum:translate>",
		loading: "<lum:translate>STR_HCM_LOADING</lum:translate>",
		empty: "<lum:translate>STR_HCM_EMPTY</lum:translate>",
		loadMore: "<lum:translate>STR_HCM_LOAD_MORE</lum:translate>",
		childrenOne: "<lum:translate>STR_HCM_CHILDREN_ONE</lum:translate>",
		childrenMany: "<lum:translate>STR_HCM_CHILDREN_MANY</lum:translate>",
		childrenOfOne: "<lum:translate>STR_HCM_CHILDREN_OF_ONE</lum:translate>",
		childrenOfMany: "<lum:translate>STR_HCM_CHILDREN_OF_MANY</lum:translate>",
		covered: "<lum:translate>STR_HCM_COVERED</lum:translate>",
		notPublished: "<lum:translate>STR_HCM_NOT_PUBLISHED</lum:translate>",
		hidden: "<lum:translate>STR_HCM_HIDDEN</lum:translate>",
		none: "<lum:translate>STR_HCM_NONE</lum:translate>",
		markedOne: "<lum:translate>STR_HCM_MARKED_ONE</lum:translate>",
		markedMany: "<lum:translate>STR_HCM_MARKED_MANY</lum:translate>",
		contentsOne: "<lum:translate>STR_HCM_CONTENTS_ONE</lum:translate>",
		contentsMany: "<lum:translate>STR_HCM_CONTENTS_MANY</lum:translate>",
		itemsOne: "<lum:translate>STR_HCM_ITEMS_ONE</lum:translate>",
		itemsMany: "<lum:translate>STR_HCM_ITEMS_MANY</lum:translate>",
		unknownOne: "<lum:translate>STR_HCM_UNKNOWN_ONE</lum:translate>",
		unknownMany: "<lum:translate>STR_HCM_UNKNOWN_MANY</lum:translate>",
		error: "<lum:translate>STR_HCM_ERROR</lum:translate>",
		forbidden: "<lum:translate>STR_HCM_FORBIDDEN</lum:translate>"
	};

	// marks: content id -> ids of its ancestors, root first, up to the parent.
	var state = { originId: null, marks: new Map(), breadcrumb: [], items: [], total: 0, parentId: null,
		generation: 0, countSeq: 0, countTimer: null, notice: "", summary: "", focusOnOpen: false };
	var crumbs = document.getElementById("hcmCrumbs");
	var list = document.getElementById("hcmList");
	var more = document.getElementById("hcmMore");
	var moreButton = document.getElementById("hcmMoreButton");
	var status = document.getElementById("hcmStatus");
	var announce = document.getElementById("hcmAnnounce");
	var hidden = document.getElementById("selectedContentIds");

	function format(template) {
		var args = arguments;
		return template.replace(/\{(\d+)\}/g, function (match, index) { return String(args[Number(index) + 1]); });
	}
	function plural(count, one, many) { return format(count === 1 ? one : many, count); }
	function originId() {
		var select = document.getElementById("originServiceInstanceId");
		return select && select.value ? select.value : null;
	}
	function writeHidden() { hidden.value = Array.from(state.marks.keys()).join(","); }
	function setStatus(message) { status.textContent = message; }
	function el(tag, attributes, children) {
		var node = document.createElement(tag);
		Object.keys(attributes || {}).forEach(function (key) { node.setAttribute(key, attributes[key]); });
		(children || []).forEach(function (child) { node.appendChild(typeof child === "string" ? document.createTextNode(child) : child); });
		return node;
	}
	function currentPath() { return state.breadcrumb.map(function (crumb) { return crumb.contentId; }); }
	function isCovered() { return state.breadcrumb.some(function (crumb) { return state.marks.has(crumb.contentId); }); }
	function hasMarkedDescendant(contentId) {
		var found = false;
		state.marks.forEach(function (path) { if (path.indexOf(contentId) >= 0) { found = true; } });
		return found;
	}
	function request(url, options) {
		options = options || {};
		options.credentials = "same-origin";
		options.headers = Object.assign({ "Accept": "application/json" }, options.headers || {});
		return fetch(url, options).then(function (response) {
			if (response.status === 403) { throw new Error("forbidden"); }
			if (!response.ok) { throw new Error("failed"); }
			return response.json();
		});
	}
	function failMessage(error) { return error && error.message === "forbidden" ? text.forbidden : text.error; }
	function postSelection(contentIds) {
		return request(BASE + "/selection", { method: "POST", headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ serviceInstanceId: state.originId, contentIds: contentIds }) });
	}

	function levelLabel() {
		var parent = state.breadcrumb[state.breadcrumb.length - 1];
		return parent ? format(text.level, parent.title || parent.contentId) : text.rootLevel;
	}
	function renderCrumbs() {
		crumbs.textContent = "";
		crumbs.setAttribute("aria-label", text.breadcrumb);
		var trail = [{ contentId: null, title: text.root }].concat(state.breadcrumb);
		trail.forEach(function (crumb, index) {
			var isLast = index === trail.length - 1;
			var button = el("button", { type: "button" }, [crumb.title || crumb.contentId || ""]);
			if (isLast) { button.setAttribute("aria-current", "page"); }
			button.addEventListener("click", function () { if (!isLast) { open(crumb.contentId); } });
			crumbs.appendChild(button);
			if (!isLast) { crumbs.appendChild(el("span", { "class": "hcm-sep", "aria-hidden": "true" }, ["›"])); }
		});
	}
	function renderItem(item) {
		var checkbox = el("input", { type: "checkbox", "data-content-id": item.contentId });
		checkbox.addEventListener("change", function () { toggle(item.contentId, checkbox.checked); });
		var label = el("label", {}, [checkbox, el("span", {}, [item.title || item.contentId])]);
		if (!item.published) { label.appendChild(el("span", { "class": "hcm-badge" }, [text.notPublished])); }
		if (item.hidden) { label.appendChild(el("span", { "class": "hcm-badge" }, [text.hidden])); }
		var li = el("li", { "data-content-id": item.contentId }, [label]);
		if (item.hasChildren) {
			var title = item.title || item.contentId;
			var enter = el("button", { type: "button", "class": "hcm-enter",
				"aria-label": format(item.childCount === 1 ? text.childrenOfOne : text.childrenOfMany, item.childCount, title) },
				[el("span", { "aria-hidden": "true" }, ["▸ "]), plural(item.childCount, text.childrenOne, text.childrenMany)]);
			enter.addEventListener("click", function () { open(item.contentId); });
			li.appendChild(enter);
		}
		return li;
	}
	function renderList(items) {
		list.setAttribute("aria-label", levelLabel());
		more.hidden = state.items.length >= state.total;
		if (!state.items.length) { list.appendChild(el("li", { "class": "hcm-empty" }, [text.empty])); return null; }
		var first = null;
		items.forEach(function (item) {
			var li = renderItem(item);
			if (!first) { first = li.querySelector("input"); }
			list.appendChild(li);
		});
		return first;
	}
	// Updates the existing checkboxes in place, so the focused element is never replaced.
	function updateMarks() {
		var covered = isCovered();
		list.querySelectorAll("input[data-content-id]").forEach(function (checkbox) {
			var contentId = checkbox.getAttribute("data-content-id");
			var marked = state.marks.has(contentId);
			checkbox.checked = covered || marked;
			checkbox.disabled = covered;
			checkbox.indeterminate = !covered && !marked && hasMarkedDescendant(contentId);
			if (covered) { checkbox.setAttribute("aria-describedby", "hcmCoveredHint"); }
			else { checkbox.removeAttribute("aria-describedby"); }
			checkbox.closest("li").classList.toggle("hcm-covered", covered);
		});
	}

	function load(parentId, offset) {
		var origin = state.originId;
		var generation = ++state.generation;
		list.setAttribute("aria-busy", "true");
		moreButton.disabled = true;
		if (!offset) { setStatus(text.loading); }
		var url = BASE + "/contents?serviceInstanceId=" + encodeURIComponent(origin) + (parentId ? "&parentContentId=" + encodeURIComponent(parentId) : "")
			+ "&offset=" + offset + "&limit=" + PAGE_SIZE;
		return request(url).then(function (page) {
			if (generation !== state.generation) { return null; }
			list.removeAttribute("aria-busy");
			moreButton.disabled = false;
			return page;
		}).catch(function (error) {
			if (generation !== state.generation) { return null; }
			list.removeAttribute("aria-busy");
			moreButton.disabled = false;
			setStatus(failMessage(error));
			return null;
		});
	}
	function open(parentId) {
		load(parentId, 0).then(function (page) {
			if (!page) { return; }
			state.parentId = parentId;
			state.breadcrumb = page.breadcrumb || [];
			state.items = page.items || [];
			state.total = page.total || 0;
			renderCrumbs();
			list.textContent = "";
			var first = renderList(state.items);
			updateMarks();
			showSummary();
			announce.textContent = format(text.levelOpened, levelLabel());
			if (first && state.focusOnOpen) { first.focus(); }
			state.focusOnOpen = true;
		});
	}
	function loadMore() {
		load(state.parentId, state.items.length).then(function (page) {
			if (!page) { return; }
			var items = page.items || [];
			state.items = state.items.concat(items);
			state.total = page.total || 0;
			var first = renderList(items);
			updateMarks();
			if (first) { first.focus(); }
		});
	}
	function toggle(contentId, checked) {
		if (checked) {
			if (isCovered()) { updateMarks(); return; }
			state.marks.forEach(function (path, markedId) { if (path.indexOf(contentId) >= 0) { state.marks.delete(markedId); } });
			state.marks.set(contentId, currentPath());
		} else {
			state.marks.delete(contentId);
		}
		writeHidden();
		updateMarks();
		scheduleCount();
	}
	function showSummary(selection) {
		var prefix = state.notice ? state.notice + " " : "";
		if (!state.marks.size) { setStatus(prefix + text.none); return; }
		if (selection) {
			state.summary = [plural(state.marks.size, text.markedOne, text.markedMany),
				plural(selection.contentCount, text.contentsOne, text.contentsMany),
				plural(selection.localeCount, text.itemsOne, text.itemsMany)].join("; ") + ".";
		}
		setStatus(prefix + state.summary);
	}
	// Counts never change the marks; a late response or error is ignored.
	function scheduleCount() {
		var seq = ++state.countSeq;
		window.clearTimeout(state.countTimer);
		if (!state.marks.size) { showSummary(); return; }
		state.countTimer = window.setTimeout(function () {
			postSelection(Array.from(state.marks.keys())).then(function (selection) {
				if (seq === state.countSeq) { showSummary(selection); }
			}).catch(function (error) {
				if (seq === state.countSeq) { setStatus(failMessage(error)); }
			});
		}, COUNT_DELAY);
	}
	// Restores the marks kept in the hidden field after any re-render of the form.
	function restore() {
		var ids = hidden.value ? hidden.value.split(",").filter(function (id) { return id; }) : [];
		ids.forEach(function (id) { state.marks.set(id, []); });
		if (!ids.length) { return; }
		var seq = ++state.countSeq;
		postSelection(ids).then(function (selection) {
			var unknown = selection.unknownContentIds || [];
			unknown.forEach(function (id) { state.marks.delete(id); });
			var paths = selection.paths || {};
			state.marks.forEach(function (path, id) { if (paths[id]) { state.marks.set(id, paths[id]); } });
			if (unknown.length) { state.notice = plural(unknown.length, text.unknownOne, text.unknownMany); writeHidden(); }
			updateMarks();
			if (seq === state.countSeq && !unknown.length) { showSummary(selection); }
			else { scheduleCount(); }
		}).catch(function (error) {
			if (seq === state.countSeq) { setStatus(failMessage(error)); }
		});
	}
	function init() {
		state.originId = originId();
		state.marks = new Map();
		state.focusOnOpen = false;
		moreButton.textContent = text.loadMore;
		document.getElementById("hcmCoveredHint").textContent = text.covered;
		renderCrumbs();
		list.textContent = "";
		if (!state.originId) { writeHidden(); setStatus(text.chooseOrigin); return; }
		restore();
		open(null);
	}
	// Only a change of origin discards the marks.
	function clear() {
		state.marks = new Map();
		state.notice = "";
		state.summary = "";
		state.countSeq++;
		window.clearTimeout(state.countTimer);
		writeHidden();
		updateMarks();
	}
	moreButton.addEventListener("click", loadMore);
	window.contentmigratorHierarchyBrowser = { clear: clear };
	init();
})();

